package app.unifeed.mail;
import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.mail.internet.MimeMessage; import java.util.*; import org.slf4j.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.kafka.annotation.RetryableTopic; import org.springframework.mail.javamail.*; import org.springframework.stereotype.Component; import org.thymeleaf.TemplateEngine; import org.thymeleaf.context.Context;
@Component public class EmailEventConsumer {private static final Logger log=LoggerFactory.getLogger(EmailEventConsumer.class);private final JdbcTemplate jdbc;private final JavaMailSender mail;private final TemplateEngine templates;private final ObjectMapper mapper;public EmailEventConsumer(JdbcTemplate j,JavaMailSender m,TemplateEngine t,ObjectMapper o){jdbc=j;mail=m;templates=t;mapper=o;}
 @RetryableTopic(attempts="3",dltTopicSuffix="-dlq",retryTopicSuffix="-retry") @KafkaListener(topics="email-events",groupId="unifeed-email-worker") public void consume(Object payload)throws Exception{Map<String,Object> event=mapper.convertValue(payload,new com.fasterxml.jackson.core.type.TypeReference<>(){});UUID eventId=UUID.fromString(event.get("eventId").toString());if(jdbc.update("INSERT INTO processed_events(event_id,event_type) VALUES(?,?) ON CONFLICT DO NOTHING",eventId,event.get("eventType"))==0)return;String language=Set.of("tr","en").contains(event.get("language"))?event.get("language").toString():"en";Context context=new Context(Locale.forLanguageTag(language));Object data=event.get("templateData");if(data instanceof Map<?,?> map)map.forEach((k,v)->context.setVariable(k.toString(),v));String html=templates.process("email/"+event.get("eventType")+"_"+language,context);MimeMessage message=mail.createMimeMessage();MimeMessageHelper helper=new MimeMessageHelper(message,true,"UTF-8");helper.setTo(event.get("recipientEmail").toString());helper.setSubject("UniFeed");helper.setText(html,true);mail.send(message);log.info("Email event processed: type={}",event.get("eventType"));}}
